def numSimilarGroups(strs):
    # Helper to check if two strings are similar
    def is_similar(a, b):
        diff = []
        for i in range(len(a)):
            if a[i] != b[i]:
                diff.append(i)
                # Early exit if more than 2 diff found
                if len(diff) > 2:
                    return False
        return len(diff) == 2 or len(diff) == 0

    # Disjoint Set Union with path compression
    parent = [i for i in range(len(strs))]

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootY] = rootX

    n = len(strs)
    for i in range(n):
        for j in range(i+1, n):
            if is_similar(strs[i], strs[j]):
                union(i, j)

    # Count number of root parents (groups)
    return sum(1 for i in range(n) if find(i) == i)
